/* SRE & Cloud Deployment Foundations — question banks for M05–M08.

   Each module: ten original bank items (q-mNN-bKK) plus five unseen gate
   variants (q-mNN-gKK) that are different questions with different choice
   sets, not reordered. Types: mcq, predict (output/config context),
   diagnose (context + choose the cause), order (steps in correct order),
   explain (rubric + model answer, self-reviewed). Selected-response items
   list the correct choice first; the gate shuffles positions. Every item
   has a rationale, misconception feedback, difficulty 1–3, objective tags
   and a remediation lesson. Diagnosis over flag trivia. Review prompts for
   each module are pushed onto LX.sreReviews at the end. */
window.LX = window.LX || { commands: [], scenarios: [], drills: [] };
LX.sreQuestions = LX.sreQuestions || [];
LX.sreReviews = LX.sreReviews || [];

(function () {
  var Q = function (x) { LX.sreQuestions.push(x); };

  /* ═══ M05 · Cloud architecture and access ═══════════════════════ */
  Q({ id: 'q-m05-b01', moduleId: 'M05', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m05-01'], remediation: 'les-m05-01',
    context: '$ curl -si https://api.beacon.corp.lab/healthz | head -3\nHTTP/2 503\nserver: awselb/2.0\ncontent-type: text/html\n$ aws elbv2 describe-target-health --target-group-arn arn:aws:elasticloadbalancing:us-east-1:123456789012:targetgroup/beacon-api/9a1b\n  "TargetHealth": { "State": "unhealthy", "Reason": "Target.Timeout", "Description": "Request timed out" }\n  "TargetHealth": { "State": "unhealthy", "Reason": "Target.Timeout", "Description": "Request timed out" }',
    q: 'Both Beacon tasks log `listening on 0.0.0.0:8080`. Which hop is failing, and what is the discriminating check?',
    choices: ['Packets from the ALB are being dropped before reaching the tasks: check the task security group allows 8080 from the ALB security group (and the subnet NACL return path)', 'Beacon is crashing on the health check path: read the task logs for a traceback', 'DNS is returning the wrong address: run `dig` against the ALB name', 'The IAM task role lacks permission to answer health checks: review the role policy'],
    a: 0, rationale: '`Target.Timeout` means the health check never got a reply, which is a drop (security group or NACL), not a refusal or an application error. A 404 or 500 would be `ResponseCodeMismatch`. DNS is fine because the ALB answered; IAM is never consulted for data-plane traffic.',
    misconception: 'Treating a timeout as an application failure skips the filter hops; a timeout is almost always a security group, NACL or route.' });
  Q({ id: 'q-m05-b02', moduleId: 'M05', pool: 'bank', type: 'predict', difficulty: 3, objectiveIds: ['obj-m05-02'], remediation: 'les-m05-02',
    context: '# identity policy on role beacon-worker\n{ "Effect": "Allow", "Action": "s3:*", "Resource": "*" }\n\n# SCP on the account\n{ "Effect": "Deny", "Action": "s3:PutObject", "Resource": "*",\n  "Condition": { "StringNotEquals": { "s3:x-amz-server-side-encryption": "aws:kms" } } }\n\n# request\nPutObject s3://beacon-ingest-looped-foundations/raw/sensor-0042.json  (no encryption header)',
    q: 'Predict the result of the request and the reason the service gives.',
    choices: ['Denied: the SCP\'s explicit Deny matches because the header is absent, and an explicit deny wins over the identity Allow', 'Allowed: `s3:*` on `*` grants everything and SCPs only apply to IAM users', 'Allowed: the Deny only applies when the header is present with a different value', 'Denied: the identity policy must name the bucket ARN explicitly'],
    a: 0, rationale: 'Evaluation starts with explicit denies in any applicable policy. `StringNotEquals` on an absent key evaluates true, so the Deny matches and ends evaluation. The Allow on `*` never gets a vote.',
    misconception: 'Readers often believe a broad Allow overrides narrower Denies, or that an absent header makes a `StringNotEquals` condition fail.' });
  Q({ id: 'q-m05-b03', moduleId: 'M05', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m05-02', 'obj-m05-01'], remediation: 'les-m05-02',
    q: 'A worker that has been uploading successfully for 59 minutes starts failing every AWS call at once with `ExpiredToken: The security token included in the request is expired`. What happened and what is the fix?',
    choices: ['The STS role session reached its expiry; obtain a new session and let the SDK manage credential refresh instead of copying credentials into the environment', 'An administrator removed a permission from the role; re-add it', 'The KMS key was disabled; re-enable it', 'The bucket policy was changed to deny the worker; edit the bucket policy'],
    a: 0, rationale: 'Every call failing at the same instant with an expiry message is a session boundary, not a policy change. Policies were not consulted; a fresh AssumeRole fixes it, and SDK-managed credentials refresh automatically.',
    misconception: '`ExpiredToken` is read as a permissions problem, leading to policy edits that change nothing.' });
  Q({ id: 'q-m05-b04', moduleId: 'M05', pool: 'bank', type: 'diagnose', difficulty: 3, objectiveIds: ['obj-m05-02'], remediation: 'les-m05-02',
    context: '$ aws s3 cp s3://beacon-ingest-looped-foundations/raw/sensor-0042.json .\nfatal error: An error occurred (AccessDenied) when calling the GetObject operation: User: arn:aws:sts::123456789012:assumed-role/beacon-worker/task-1 is not authorized to perform: kms:Decrypt on resource: arn:aws:kms:us-east-1:123456789012:key/4f1c-... with an explicit deny in a resource-based policy\n$ aws iam simulate-principal-policy --policy-source-arn arn:aws:iam::123456789012:role/beacon-worker --action-names s3:GetObject --resource-arns arn:aws:s3:::beacon-ingest-looped-foundations/raw/sensor-0042.json\n  "EvalDecision": "allowed"',
    q: 'S3 permission is allowed by the simulator, yet the download fails. Where is the denial and what is the narrow change?',
    choices: ['The KMS key policy explicitly denies the role `kms:Decrypt`; change the key policy statement for this role only (or use a key whose policy admits it), leaving the S3 policies alone', 'The S3 bucket policy denies GetObject; add an Allow for the role to the bucket policy', 'The role session expired; assume the role again', 'The object is in a different region; add `--region`'],
    a: 0, rationale: 'The error names `kms:Decrypt` and "explicit deny in a resource-based policy": the key policy. The simulator only evaluated the S3 action. Reading SSE-KMS objects requires Decrypt on the key, and the key policy is the root of authority for it.',
    misconception: 'An `AccessDenied` from S3 is assumed to be an S3 policy problem; with SSE-KMS the key policy is a separate gate.' });
  Q({ id: 'q-m05-b05', moduleId: 'M05', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m05-03'], remediation: 'les-m05-03',
    context: '# route table rtb-private-az2 (associated with subnet 10.40.11.0/24, use1-az2)\n10.40.0.0/16     local\npl-63a5400a      vpce-0a1b2c3d   # gateway endpoint, com.amazonaws.us-east-1.s3\n\n# interface endpoints in the VPC: none\n# NAT gateways: none',
    q: 'From a worker task in 10.40.11.0/24, predict the outcome of (1) `aws s3 ls s3://beacon-ingest-looped-foundations/` and (2) `aws sts get-caller-identity`.',
    choices: ['(1) succeeds via the gateway endpoint; (2) times out because STS has no interface endpoint and there is no NAT route', 'Both succeed: AWS APIs are always reachable from inside a VPC', 'Both time out: a gateway endpoint needs a NAT gateway to function', '(1) times out and (2) succeeds: STS is a global service and S3 needs a public address'],
    a: 0, rationale: 'The gateway endpoint adds a route for S3\'s prefix list only. STS lives on a public endpoint reachable only through a NAT route or its own interface endpoint; with neither, the connection has no route and times out.',
    misconception: 'Learners treat "inside AWS" as "can reach AWS APIs"; each service needs a path (NAT, interface endpoint or gateway endpoint).' });
  Q({ id: 'q-m05-b06', moduleId: 'M05', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m05-03'], remediation: 'les-m05-03',
    q: 'Which layout keeps two availability zones as independent failure domains for private-subnet egress?',
    choices: ['One NAT gateway per AZ, each private subnet\'s route table pointing at the NAT in its own AZ', 'One NAT gateway in az1, both private route tables pointing at it, since NAT gateways are highly available', 'An internet gateway route on the private subnets, since the IGW is regional', 'A gateway endpoint for every service so no NAT is needed'],
    a: 0, rationale: 'A NAT gateway is bound to its subnet\'s AZ. Routing az2 through az1\'s NAT makes az2\'s egress depend on az1. Gateway endpoints exist only for S3 and DynamoDB, and an IGW route makes the subnet public.',
    misconception: '"Highly available" within one AZ is mistaken for cross-AZ independence; the route table decides the dependency.' });
  Q({ id: 'q-m05-b07', moduleId: 'M05', pool: 'bank', type: 'explain', difficulty: 2, objectiveIds: ['obj-m05-04'], remediation: 'les-m05-04',
    q: 'Beacon\'s PostgreSQL will run either as RDS Multi-AZ or self-managed on an EC2 pair with EBS. Write the decision in the four-line form this course requires (requirement, chosen option, rejected option with what it offered, cost in money and work) for a service with RPO 1 minute and RTO 5 minutes.',
    rubric: ['States the requirement in numbers (RPO 1 min, RTO 5 min) and ties it to a mechanism', 'Names RDS Multi-AZ as meeting it with synchronous standby and 1–2 minute failover without a runbook', 'Names the rejected option honestly: cheaper per month, full control, but failover and WAL archiving are work you own and must test', 'States the cost of the chosen option (roughly double single-AZ) as accepted, and notes what Multi-AZ does not cover (logical corruption, region)'],
    answer: 'Requirement: RPO 1 minute, RTO 5 minutes for the readings database, private only. Chosen: RDS PostgreSQL Multi-AZ — synchronous standby in the second AZ gives RPO near zero and automatic failover in one to two minutes with no runbook, plus point-in-time recovery for logical errors. Rejected: PostgreSQL on an EC2 pair with EBS and streaming replication — cheaper and fully controllable, but failover, WAL archiving, patching and quarterly failover tests become our work and the measured RTO is unproven. Cost: about twice the single-AZ price, accepted; still does not cover a region loss or a destructive migration, which need PITR and a cross-region snapshot copy.',
    rationale: 'A decision is reviewable only when the requirement, both options and the cost are written so someone can disagree with a reason.',
    misconception: 'Choosing "managed because it is better" without the requirement or the rejected option\'s merits is a habit, not a design decision.' });
  Q({ id: 'q-m05-b08', moduleId: 'M05', pool: 'bank', type: 'order', difficulty: 2, objectiveIds: ['obj-m05-05'], remediation: 'les-m05-05',
    q: 'Order the steps of the AZ-loss recovery plan for Beacon as this course writes it (az1 lost; RDS Multi-AZ; Fargate tasks in both AZs; one NAT per AZ).',
    steps: ['Confirm the RDS failover completed from the RDS events and the writer endpoint resolves to the az2 instance', 'Confirm the ALB has healthy targets in az2', 'Scale the az2 service up to the full task count', 'Verify the az2 NAT route carries egress for image pulls and third-party calls', 'Verify the user path with a real POST through the public name', 'Record the measured time against the RTO target'],
    rationale: 'Data first (is the database writable), then the path to it (healthy targets), then capacity, then dependencies of that capacity, then proof on the user path, then the evidence that turns the plan into a measured number.',
    misconception: 'Plans that start with scaling or end without a user-path check restore capacity nobody can reach and never learn the real RTO.' });
  Q({ id: 'q-m05-b09', moduleId: 'M05', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m05-05'], remediation: 'les-m05-05',
    q: 'A migration dropped the `readings` table at 09:40 on an RDS Multi-AZ instance. Which mechanism recovers the data, and why does the standby not help?',
    choices: ['Point-in-time recovery to 09:39 into a new instance, then verify and repoint; the standby replicated the drop synchronously within a second', 'Trigger a Multi-AZ failover; the standby lags by minutes so it still has the table', 'Restore from the most recent automated snapshot only; PITR cannot target a minute', 'Scale the instance class up so PostgreSQL can undo the transaction'],
    a: 0, rationale: 'Multi-AZ protects against instance and AZ loss by replicating every write, including destructive ones. Logical faults need a copy from before the fault: PITR to a chosen minute within the retention window.',
    misconception: '"We have a standby" is mistaken for "we have backups"; replication and recovery are different mechanisms with different RPOs.' });
  Q({ id: 'q-m05-b10', moduleId: 'M05', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m05-03', 'obj-m05-01'], remediation: 'les-m05-03',
    context: '# from a worker task in the private subnet\n$ dig +short kms.us-east-1.amazonaws.com\n52.46.141.23\n$ aws kms describe-key --key-id alias/beacon-ingest\nConnect timeout on endpoint URL: "https://kms.us-east-1.amazonaws.com/"\n$ aws ec2 describe-vpc-endpoints --query "VpcEndpoints[].{svc:ServiceName,dns:PrivateDnsEnabled}"\n[ { "svc": "com.amazonaws.us-east-1.kms", "dns": false } ]',
    q: 'An interface endpoint for KMS exists, yet the call times out. What is the cause?',
    choices: ['Private DNS is disabled on the endpoint, so the hostname resolves to the public address, which has no route from the private subnet', 'The task role lacks `kms:DescribeKey`; IAM returns a timeout for denied calls', 'The KMS key is in another region', 'The gateway endpoint for KMS is missing a route table association'],
    a: 0, rationale: 'An interface endpoint is used only when the service hostname resolves to its private address; with `PrivateDnsEnabled: false` the public address is returned and the private subnet has no path to it. IAM denials are explicit errors, not timeouts, and KMS has no gateway endpoint type.',
    misconception: 'Creating the endpoint is assumed to redirect traffic; the DNS answer is what decides the path.' });

  Q({ id: 'q-m05-g01', moduleId: 'M05', pool: 'gate', type: 'predict', difficulty: 3, objectiveIds: ['obj-m05-02'], remediation: 'les-m05-02',
    context: '# permission boundary attached to role beacon-worker\n{ "Effect": "Allow", "Action": ["s3:GetObject", "s3:PutObject"], "Resource": "arn:aws:s3:::beacon-ingest-looped-foundations/*" }\n\n# identity policy on role beacon-worker\n{ "Effect": "Allow", "Action": ["s3:*", "sqs:*"], "Resource": "*" }\n\n# request\nsqs:ReceiveMessage on arn:aws:sqs:us-east-1:123456789012:beacon-ingest',
    q: 'Predict the evaluation result for the request.',
    choices: ['Denied: the permission boundary does not allow any `sqs:` action, and a boundary caps what the identity policy can grant', 'Allowed: the identity policy allows `sqs:*` and boundaries only restrict S3', 'Allowed: boundaries apply to IAM users, not roles', 'Denied: `sqs:ReceiveMessage` needs a resource-based policy on the queue in every case'],
    a: 0, rationale: 'With a boundary, the effective permission is the intersection of the boundary and the identity policy. The boundary allows two S3 actions only, so every SQS action is implicitly denied regardless of the identity Allow.',
    misconception: 'A boundary is read as "extra permissions" rather than a ceiling; it never grants and it applies to roles.' });
  Q({ id: 'q-m05-g02', moduleId: 'M05', pool: 'gate', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m05-01'], remediation: 'les-m05-01',
    context: '$ curl -s -o /dev/null -w "%{http_code}\\n" -X POST https://api.beacon.corp.lab/v1/status -d @sample.json\n502\n$ aws elbv2 describe-target-health --target-group-arn <tg> --query "TargetHealthDescriptions[].TargetHealth.State"\n[ "healthy", "healthy" ]\n$ aws logs tail /beacon/api --since 2m | grep -c "POST /v1/status"\n0',
    q: 'Targets are healthy, GET /healthz works, and POSTs return 502 with no Beacon log line. Which hypothesis fits all three observations?',
    choices: ['The ALB opened a connection to a target for the POST and the target closed it or replied malformed before Beacon logged — look at the request size or body handling (e.g. a body size or header the app rejects at the socket layer) at the target', 'The security group blocks the ALB, which produces 502s', 'DNS points at the wrong load balancer', 'The task role is missing `logs:PutLogEvents`, so Beacon cannot start'],
    a: 0, rationale: '502 is the ALB saying the target misbehaved on that connection; health checks and GETs succeed so the path is open (a security group block would be a timeout and unhealthy targets). The absence of a log line localises the failure to before Beacon\'s handler ran, on the target.',
    misconception: 'A 502 is mistaken for a network block; blocks time out, while 502 means a connection reached a target and went wrong there.' });
  Q({ id: 'q-m05-g03', moduleId: 'M05', pool: 'gate', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m05-03'], remediation: 'les-m05-03',
    q: 'Beacon\'s private subnets need S3, KMS and ECR with no internet egress at all. Which combination delivers that?',
    choices: ['A gateway endpoint for S3 on the private route tables, plus interface endpoints with private DNS for KMS and ECR (api and dkr) in both AZs, and no NAT route', 'A NAT gateway per AZ; endpoints are only for cost saving', 'Interface endpoints for all three; S3 has no gateway type', 'A single gateway endpoint for S3, KMS and ECR together'],
    a: 0, rationale: 'S3 (and DynamoDB) use gateway endpoints as route entries; everything else uses interface endpoints. Placing interface endpoints in both AZs keeps them out of a single failure domain, and removing the NAT route is what "no egress" means.',
    misconception: 'Gateway and interface endpoints are treated as interchangeable, or NAT is assumed necessary for any AWS API call.' });
  Q({ id: 'q-m05-g04', moduleId: 'M05', pool: 'gate', type: 'explain', difficulty: 2, objectiveIds: ['obj-m05-05', 'obj-m05-04'], remediation: 'les-m05-05',
    q: 'Beacon runs in two availability zones with RDS Multi-AZ. Name three failure classes that two AZs do not protect against and the mechanism each one needs.',
    rubric: ['Region loss: cross-region snapshot copies and a documented rebuild, with an honest RTO in hours', 'A bad deploy reaches both AZs: gradual rollout gated on health with rollback', 'Logical data corruption is replicated synchronously: point-in-time recovery or a pre-fault backup', 'Also acceptable: expired certificate / deleted role / vendor outage as account- or vendor-scoped faults needing their own inventory rows'],
    answer: 'Two AZs remove one failure domain. A region outage takes both, so the plan needs cross-region snapshot copies and a rehearsed rebuild. A broken release deploys to both AZs at once, so rollouts must be gradual, gated on a health signal and reversible. A destructive write or migration is replicated to the standby within a second, so only point-in-time recovery or a backup from before the fault restores the data. Account-scoped faults such as an expired certificate or a deleted IAM role, and vendor faults such as the registry being down, are also unaffected by AZ count and belong in the inventory with their own mitigation or an explicit acceptance.',
    rationale: 'Naming what Multi-AZ does not cover is the debrief question for this module; each class maps to a distinct mechanism.',
    misconception: 'Multi-AZ is equated with disaster recovery, hiding the deploy, data and region classes.' });
  Q({ id: 'q-m05-g05', moduleId: 'M05', pool: 'gate', type: 'order', difficulty: 2, objectiveIds: ['obj-m05-02'], remediation: 'les-m05-02',
    q: 'Order the steps for narrowing the beacon-worker role to least privilege without removing a boundary others rely on.',
    steps: ['Collect the observed actions and resources for the role from CloudTrail or last-accessed data', 'Write an Allow with specific actions and resource ARNs, adding conditions where they add safety', 'Leave existing Deny statements and the permission boundary untouched', 'Test with the policy simulator: the required request is allowed and a request that must stay denied is still denied', 'Apply the change on a branch with a focused diff and verify the worker\'s real upload succeeds'],
    rationale: 'Observe first, then write the narrow Allow, preserve the other boundaries, prove both directions with the simulator, then apply and verify on the real path.',
    misconception: 'Deleting a Deny to make an Allow work widens access for every principal the Deny covered.' });

  /* ═══ M06 · Terraform and desired state ═════════════════════════ */
  Q({ id: 'q-m06-b01', moduleId: 'M06', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m06-02'], remediation: 'les-m06-02',
    context: 'Terraform will perform the following actions:\n\n  # docker_container.api must be replaced\n-/+ resource "docker_container" "api" {\n      ~ id      = "7f3c9a..." -> (known after apply)\n      ~ image   = "sha256:aa11..." -> "sha256:bb22..." # forces replacement\n        name    = "beacon-api"\n      ~ restart = "no" -> "unless-stopped"\n    }\n\n  # docker_image.beacon will be updated in-place\n  ~ resource "docker_image" "beacon" {\n      ~ name = "registry.lab/beacon/api:1.4.2" -> "registry.lab/beacon/api:1.4.3"\n    }',
    q: 'Predict the summary line and what happens to the container\'s writable layer.',
    choices: ['`Plan: 1 to add, 1 to change, 1 to destroy.` — the container is destroyed and recreated, so its writable layer is lost; the image resource is updated in place', '`Plan: 0 to add, 2 to change, 0 to destroy.` — both resources update in place and nothing is lost', '`Plan: 2 to add, 0 to change, 0 to destroy.` — two new objects are created beside the old ones', '`Plan: 0 to add, 1 to change, 1 to destroy.` — the container is destroyed and not recreated'],
    a: 0, rationale: 'A replacement (`-/+`) counts as one add and one destroy; `image` carries `# forces replacement`. The `restart` change rides along but is not the cause. The writable layer belongs to the destroyed container.',
    misconception: 'Reading `~ restart` as the whole change, or counting a replacement as a single "change".' });
  Q({ id: 'q-m06-b02', moduleId: 'M06', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m06-04'], remediation: 'les-m06-03',
    context: '$ terraform plan\n│ Error: Error acquiring the state lock\n│ Lock Info:\n│   ID:        9c1f2e4a-5b3d-4e2f-9a1c-7d8e6f5a4b3c\n│   Path:      looped-foundations-tfstate/beacon/staging/terraform.tfstate\n│   Operation: OperationTypeApply\n│   Who:       ci@runner-12\n│   Created:   2026-10-13 09:41:18 UTC\n$ date -u\nMon Oct 13 09:52:03 UTC 2026\n# pipeline UI: run #418 on runner-12 — status: running, step "terraform apply" (started 09:41)',
    q: 'What is the correct action?',
    choices: ['Wait: the holder is a live apply on runner-12; breaking the lock would let two writers corrupt the state', 'Run `terraform force-unlock 9c1f2e4a-...`: eleven minutes is too long for a lock', 'Delete the `.tflock` object in the bucket by hand and retry', 'Switch to a DynamoDB table so locks expire automatically'],
    a: 0, rationale: 'Elapsed time is not evidence. The pipeline shows the holder still executing its apply, so the lock is active. Force-unlock or deleting the lock object is only correct for a holder that is confirmed dead.',
    misconception: 'Lock age is mistaken for staleness; staleness is about whether the holder is still running.' });
  Q({ id: 'q-m06-b03', moduleId: 'M06', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m06-04'], remediation: 'les-m06-03',
    q: 'Which backend configuration is the supported way to lock Terraform state in S3 at the course\'s pinned versions?',
    choices: ['`backend "s3" { ... use_lockfile = true }` — the lock is an object beside the state; the `dynamodb_table` argument is deprecated', '`backend "s3" { ... dynamodb_table = "tf-locks" }` — a table is the only locking mechanism for S3', '`backend "local"` with a shared NFS mount', 'No locking is needed if every apply runs from the pipeline'],
    a: 0, rationale: 'The S3 backend locks with `use_lockfile = true` using conditional writes on a `.tflock` object. DynamoDB-based locking still functions but is deprecated and should not be introduced in new configurations. Pipelines can run concurrently, so locking is still needed.',
    misconception: 'Older guidance is copied forward; the current backend documents the lockfile mechanism and marks the table argument deprecated.' });
  Q({ id: 'q-m06-b04', moduleId: 'M06', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m06-03'], remediation: 'les-m06-03',
    context: '# yesterday, during an incident, by hand:\n$ docker update --restart=always beacon-api\n\n# main.tf\nresource "docker_container" "api" {\n  name    = "beacon-api"\n  image   = docker_image.beacon.image_id\n  restart = "unless-stopped"\n}',
    q: 'Predict what `terraform plan` proposes today and what `terraform plan -refresh-only` shows instead.',
    choices: ['Plan: update `restart` in place from `always` back to `unless-stopped`. Refresh-only: reports the object changed outside Terraform (`unless-stopped` -> `always`) with no proposed action', 'Both show no changes; Terraform does not track `restart`', 'Plan: replace the container because `restart` forces replacement. Refresh-only: the same replacement', 'Plan: no changes, because the state was updated by `docker update`. Refresh-only: an error'],
    a: 0, rationale: 'Plan refreshes, sees drift, and proposes to converge the object to the configuration — reverting the hand edit. Refresh-only surfaces the drift without proposing to act, so you can choose to update the configuration or accept reality into state.',
    misconception: 'Learners expect out-of-band edits to be invisible or to update the state automatically; the plan silently reverts them.' });
  Q({ id: 'q-m06-b05', moduleId: 'M06', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m06-03'], remediation: 'les-m06-03',
    q: 'The network `beacon-net` was created by hand before Terraform. Which sequence brings it under management with a reviewable change?',
    choices: ['Write the `resource "docker_network" "lab"` block and an `import { to = docker_network.lab, id = "beacon-net" }` block, plan (shows "will be imported"), apply, then iterate on the block until `plan` prints `No changes`', 'Add the resource block and apply; Terraform detects the existing name and adopts it', 'Delete the network, then let Terraform create it fresh', 'Run `terraform state push` with a hand-written state entry'],
    a: 0, rationale: 'Import blocks make the adoption part of a plan that is reviewed and repeatable. Applying a new resource block for an existing name fails or creates a duplicate; deleting destroys what you were trying to keep.',
    misconception: 'Terraform is assumed to discover existing objects by name; it only knows what the state maps.' });
  Q({ id: 'q-m06-b06', moduleId: 'M06', pool: 'bank', type: 'diagnose', difficulty: 3, objectiveIds: ['obj-m06-02', 'obj-m06-03'], remediation: 'les-m06-04',
    context: '  # docker_container.db must be replaced\n-/+ resource "docker_container" "db" {\n      ~ id    = "c41e..." -> (known after apply)\n      ~ image = "sha256:9d2f..." -> "sha256:e07b..." # forces replacement\n        name  = "beacon-db"\n        # (no volumes block)\n    }\n\nPlan: 1 to add, 0 to change, 1 to destroy.\n\n$ docker exec beacon-db psql -U beacon -c "select count(*) from readings"\n 184203',
    q: 'What is at risk if this plan is applied, and what is the correct path?',
    choices: ['All 184203 rows: the data directory is in the container\'s writable layer with no volume, so the replacement destroys it. Dump first, add a `docker_volume` to the configuration, apply, restore, verify counts', 'Nothing: PostgreSQL data is always on a volume', 'Only a few seconds of downtime: image changes keep the filesystem', 'The image: the new one may not pull, so run `docker pull` first'],
    a: 0, rationale: 'With no `volumes` block the data lives in the container, and `-/+` destroys the container. The plan cannot know that; the annotation must. The safe path moves the data to a volume before any replacement.',
    misconception: '`1 to destroy` is read as "one object" rather than "everything inside it that is not stored elsewhere".' });
  Q({ id: 'q-m06-b07', moduleId: 'M06', pool: 'bank', type: 'mcq', difficulty: 1, objectiveIds: ['obj-m06-01'], remediation: 'les-m06-01',
    q: 'What does `.terraform.lock.hcl` record, and what should happen to it?',
    choices: ['The exact provider versions and checksums selected by `init`, so every machine computes the same plan; commit it and move it forward deliberately with `init -upgrade`', 'The state lock held by the current run; delete it when a run finishes', 'The resource addresses in the state; regenerate it on every apply', 'Cached provider binaries; add it to `.gitignore`'],
    a: 0, rationale: 'The lockfile pins providers, not state. Without it the pipeline silently picks a newer provider and plans differ between machines.',
    misconception: 'The word "lock" makes people confuse the provider lockfile with the state lock.' });
  Q({ id: 'q-m06-b08', moduleId: 'M06', pool: 'bank', type: 'explain', difficulty: 2, objectiveIds: ['obj-m06-05'], remediation: 'les-m06-05',
    q: 'Explain, in three to five sentences, what Terraform owns and what a configuration-management tool like Ansible owns for Beacon on EC2, and name one thing each will never notice about the other\'s layer.',
    rubric: ['Terraform owns whether objects exist and their shape (VPC, roles, instances, ALB, RDS) via a plan and a state file', 'Configuration management owns what happens inside a host (packages, files, services) idempotently but without a state file', 'Terraform never sees a package installed by hand inside the instance; CM never knows the instance was planned for destruction', 'Names a stated hand-off (image build or user-data/CM run after create) rather than Terraform provisioners'],
    answer: 'Terraform describes which objects should exist and in what shape — the VPC, subnets, roles, the instances, the ALB and the RDS instance — and uses a state file and a plan to converge reality to that description. A configuration-management tool runs inside the hosts Terraform created: it installs packages, writes files and starts services, converging each run without any state file. Terraform will never notice a package installed by hand inside an instance, and Ansible will never know that Terraform plans to destroy the host it just configured. The hand-off is explicit: Terraform creates the instance from a known image, then the CM run or the image build owns everything inside; provisioners that run shell inside instances blur the boundary and lose idempotency.',
    rationale: 'The contrast is about which layer each tool models and whether it keeps state, not about which is "better".',
    misconception: 'Treating them as competitors leads to Terraform provisioners doing CM work, or CM scripts creating cloud resources with no plan.' });
  Q({ id: 'q-m06-b09', moduleId: 'M06', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m06-05'], remediation: 'les-m06-05',
    context: '# before: main.tf\nresource "docker_container" "api" { ... }\n\n# after: main.tf\nmodule "beacon" {\n  source = "./modules/beacon"\n}\n# modules/beacon/main.tf\nresource "docker_container" "api" { ... }\n\n# no moved blocks',
    q: 'Predict the plan after this refactor.',
    choices: ['`docker_container.api will be destroyed` and `module.beacon.docker_container.api will be created`: 1 to add, 1 to destroy', 'No changes: Terraform matches resources by type and name across modules', '`docker_container.api will be updated in-place` with a new address', 'An error: resources cannot be moved between modules'],
    a: 0, rationale: 'The address changed; to Terraform that is a new object and an orphaned old one. A `moved { from = docker_container.api to = module.beacon.docker_container.api }` block makes it a rename with no changes.',
    misconception: 'A refactor is assumed to be free of runtime effect; without `moved`, it is a destroy-and-create of everything moved.' });
  Q({ id: 'q-m06-b10', moduleId: 'M06', pool: 'bank', type: 'order', difficulty: 2, objectiveIds: ['obj-m06-01', 'obj-m06-02'], remediation: 'les-m06-02',
    q: 'Order the steps of a reviewed Terraform change to bump Beacon to 1.4.3 in staging.',
    steps: ['Change `beacon_version` in `envs/staging/terraform.tfvars` on a branch', 'Run `terraform fmt -check` and `terraform validate`', 'Run `terraform plan -out=staging.tfplan` and annotate every destroy or replacement with its data consequence', 'Have the saved plan reviewed and approved', 'Run `terraform apply staging.tfplan`', 'Verify the user path and confirm a second `terraform plan` prints `No changes`'],
    rationale: 'Format and validate before planning; plan to a file so the reviewed artefact is what gets applied; verify on the user path and with a clean follow-up plan.',
    misconception: 'Applying a fresh plan after review means the thing applied may differ from the thing reviewed.' });

  Q({ id: 'q-m06-g01', moduleId: 'M06', pool: 'gate', type: 'predict', difficulty: 2, objectiveIds: ['obj-m06-02'], remediation: 'les-m06-04',
    context: 'resource "docker_container" "api" {\n  name  = "beacon-api"\n  image = docker_image.beacon.image_id\n  ports { internal = 8080  external = 8080 }\n  lifecycle { create_before_destroy = true }\n}\n\n# plan after bumping the image\n+/- resource "docker_container" "api" {\n      ~ image = "sha256:aa11..." -> "sha256:bb22..." # forces replacement\n        name  = "beacon-api"',
    q: 'Predict what happens during apply.',
    choices: ['Apply fails during the create step: the new container cannot take the name `beacon-api` or host port 8080 while the old one still exists', 'Zero-downtime replacement: the new container starts, then the old one is removed', 'Terraform updates the image in place because `create_before_destroy` disables replacement', 'The old container is destroyed first because `+/-` means destroy then create'],
    a: 0, rationale: '`+/-` creates before destroying, which requires both objects to coexist. A fixed container name and a published host port are exclusive, so the create step errors. Use a unique name and port, or accept `-/+`.',
    misconception: '`create_before_destroy` is treated as a free zero-downtime switch; it needs non-conflicting identities.' });
  Q({ id: 'q-m06-g02', moduleId: 'M06', pool: 'gate', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m06-04', 'obj-m06-03'], remediation: 'les-m06-03',
    context: '$ terraform apply\n│ Error: Error acquiring the state lock\n│   ID:        3e7a...  Operation: OperationTypeApply  Who: ci@runner-04  Created: 2026-10-13 08:12:40 UTC\n# pipeline UI: run #402 on runner-04 — FAILED at 08:14:02, step "terraform apply", exit 137 (OOM killed)\n$ terraform force-unlock 3e7a...\nTerraform state has been successfully unlocked\n$ terraform plan -refresh-only\n  # docker_container.worker has changed\n  ~ env = ["BEACON_QUEUE=ingest"] -> ["BEACON_QUEUE=ingest-v2"]\n  # (configuration already specifies BEACON_QUEUE=ingest-v2)',
    q: 'The unlock was justified. What is the right next step, and why?',
    choices: ['`terraform apply -refresh-only` to accept the already-correct reality into state, then a normal `plan` which should print `No changes`', '`terraform apply` immediately; the refresh-only output is just informational', '`terraform state rm docker_container.worker` and recreate it', 'Revert the configuration to `BEACON_QUEUE=ingest` so state and config agree'],
    a: 0, rationale: 'The killed run had already changed the object to what the configuration wants; the state is behind. Refresh-only apply updates state without touching the object. A plain apply would plan from stale state and may try to create a container whose name exists.',
    misconception: 'After a crashed apply, state is assumed to be either fully right or fully wrong; it is usually partially behind reality.' });
  Q({ id: 'q-m06-g03', moduleId: 'M06', pool: 'gate', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m06-01'], remediation: 'les-m06-01',
    q: 'A `variable "beacon_version"` has a validation block requiring a semantic version. What does `terraform plan -var beacon_version=main` do?',
    choices: ['Fails before contacting any provider with the variable\'s `error_message`', 'Plans normally; validation only runs during apply', 'Pulls the image tagged `main` and then fails if it does not exist', 'Replaces the value with the default and warns'],
    a: 0, rationale: 'Variable validation is evaluated at plan and validate time, before provider calls, so a bad input never produces a partial apply.',
    misconception: 'Validation is assumed to be a runtime check rather than a plan-time gate.' });
  Q({ id: 'q-m06-g04', moduleId: 'M06', pool: 'gate', type: 'explain', difficulty: 3, objectiveIds: ['obj-m06-05', 'obj-m06-04'], remediation: 'les-m06-05',
    q: 'Staging and production for Beacon must use different AWS accounts and different reviewers. Decide between Terraform workspaces and a directory per environment, and give the failure mode of the option you rejected.',
    rubric: ['Chooses directories per environment with separate backend keys/buckets and provider credentials', 'Explains that workspaces share one backend and one credential set and rely on `workspace select`', 'Names the failure mode: applying production from the wrong selected workspace, or credentials that can reach both', 'Notes where workspaces still fit: short-lived variants of one environment such as per-branch previews'],
    answer: 'Use a directory per environment: `envs/staging` and `envs/prod`, each with its own backend block (separate bucket or key, `use_lockfile = true`), its own provider configuration pointing at its own account, and its own review rule. Workspaces keep one configuration and one backend with several states, which means one set of credentials can reach both environments and the only thing separating a staging apply from a production apply is remembering `terraform workspace select`; the failure mode is a production change made from the wrong workspace with credentials that allowed it. Workspaces remain useful for short-lived variants of a single environment, such as a per-branch preview that shares staging\'s account.',
    rationale: 'Separation of credentials and review is a property of directories with distinct backends, not of workspaces.',
    misconception: 'Workspaces are marketed as environments; they are states behind one backend.' });
  Q({ id: 'q-m06-g05', moduleId: 'M06', pool: 'gate', type: 'order', difficulty: 2, objectiveIds: ['obj-m06-03'], remediation: 'les-m06-04',
    q: 'A plan proposes `-/+` on the PostgreSQL container, whose data is in its writable layer. Order the safe path.',
    steps: ['Do not apply the plan as written; annotate the replacement with the data consequence', 'Dump the database to a file outside the container', 'Add a `docker_volume` and a `volumes` block to the container configuration, with `prevent_destroy` on the volume', 'Apply the volume change (the container is replaced once, now mounting the volume)', 'Restore the dump into the new container and verify row counts', 'Confirm the following `terraform plan` prints `No changes`'],
    rationale: 'Protect the data before any destroy: dump, move the data location into a resource that is not replaced, apply, restore, verify, and prove convergence.',
    misconception: 'Applying because the pipeline is green treats the plan as a preview rather than a warning about data.' });

  /* ═══ M07 · Containers and image delivery ═══════════════════════ */
  Q({ id: 'q-m07-b01', moduleId: 'M07', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m07-02'], remediation: 'les-m07-03',
    context: '$ docker run -d --name beacon-api -p 8080:8080 registry.lab/beacon/api:1.4.2\n$ curl -s http://127.0.0.1:8080/healthz\ncurl: (56) Recv failure: Connection reset by peer\n$ docker port beacon-api\n8080/tcp -> 0.0.0.0:8080\n$ docker exec beacon-api ss -ltn\nState  Recv-Q Send-Q Local Address:Port  Peer Address:Port\nLISTEN 0      2048       127.0.0.1:8080       0.0.0.0:*',
    q: 'What is the cause and the smallest fix?',
    choices: ['Beacon binds the container\'s loopback, so the forwarded connection arriving on eth0 is refused; configure it to listen on 0.0.0.0:8080', 'The port is not published; add `-p 8080:8080`', 'The host firewall blocks 8080; open it', 'The image is for the wrong architecture; rebuild for amd64'],
    a: 0, rationale: '`docker port` shows the publish is in place; `ss` inside shows the listener on 127.0.0.1 only. Published traffic reaches the container\'s eth0 address, not its loopback, so it is reset. A wrong architecture would fail to start at all.',
    misconception: 'Binding 0.0.0.0 inside a container is feared as "exposing to the world"; it only exposes to the container\'s own namespace.' });
  Q({ id: 'q-m07-b02', moduleId: 'M07', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m07-04'], remediation: 'les-m07-04',
    context: '$ docker image inspect -f "{{.Config.Entrypoint}} {{.Config.Cmd}}" registry.lab/beacon/api:1.4.2\n[] [/bin/sh -c python -m beacon.api]\n# beacon.api installs no signal handlers',
    q: 'Predict `time docker stop beacon-api` and the container\'s exit code.',
    choices: ['About 10 seconds and exit code 137: `sh` is PID 1 and does not forward SIGTERM, so Docker falls back to SIGKILL', 'Under a second and exit code 0: SIGTERM terminates Python by default', 'Under a second and exit code 143: the shell forwards SIGTERM to Python', 'It never stops: shell-form containers must be killed with `docker kill`'],
    a: 0, rationale: 'The shell form makes `/bin/sh -c` PID 1; it receives SIGTERM and does nothing. After the default 10-second grace period Docker sends SIGKILL: 128 + 9 = 137.',
    misconception: 'Learners expect default SIGTERM behaviour inside containers; as PID 1 an unhandled signal is dropped, and a shell wrapper hides the process anyway.' });
  Q({ id: 'q-m07-b03', moduleId: 'M07', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m07-01'], remediation: 'les-m07-02',
    q: 'Which Dockerfile ordering keeps the dependency install cached when only Beacon\'s source changes?',
    choices: ['`COPY requirements.txt .` then `RUN pip install --no-cache-dir -r requirements.txt` then `COPY . .`', '`COPY . .` then `RUN pip install -r requirements.txt`', '`RUN pip install -r requirements.txt` then `COPY . .` (pip reads the file from the host)', 'Order does not matter; Docker caches by file content'],
    a: 0, rationale: 'The cache invalidates at the first instruction whose inputs changed and everything after it. Copying only the manifest first means a code edit invalidates the final COPY, not the install. The third option fails: the file is not in the image yet.',
    misconception: 'The cache is believed to be per-file rather than per-layer-in-order.' });
  Q({ id: 'q-m07-b04', moduleId: 'M07', pool: 'bank', type: 'diagnose', difficulty: 3, objectiveIds: ['obj-m07-05'], remediation: 'les-m07-05',
    context: '$ kubectl -n beacon logs beacon-api-6d9f-x2k7q\nexec /usr/local/bin/python: exec format error\n$ kubectl get node -o jsonpath="{.items[0].status.nodeInfo.architecture}"\namd64\n$ docker buildx imagetools inspect registry.lab/beacon/api:1.4.2\nName:      registry.lab/beacon/api:1.4.2\nMediaType: application/vnd.oci.image.manifest.v1+json\nDigest:    sha256:7c1e...\nPlatform:  linux/arm64',
    q: 'Which hypothesis survives and what is the fix?',
    choices: ['The image was built only for linux/arm64 and the node is amd64; rebuild with `docker buildx build --platform linux/amd64,linux/arm64 --push` and deploy the resulting index digest', 'The scheduler placed the Pod on a node without enough CPU; add a nodeSelector', 'The liveness probe is killing a slow start; add a startup probe', 'The entrypoint path is wrong; change it to `python3`'],
    a: 0, rationale: '`exec format error` is the kernel refusing a binary for another CPU; the manifest confirms a single arm64 platform. Scheduling and probes would show different evidence (Pending, probe events).',
    misconception: 'Crash-looping Pods are assumed to be a cluster problem; the manifest is the one-command discriminating check.' });
  Q({ id: 'q-m07-b05', moduleId: 'M07', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m07-03'], remediation: 'les-m07-05',
    context: 'services:\n  db:\n    image: postgres:16.6-bookworm\n    volumes: ["pgdata:/var/lib/postgresql/data"]\n  api:\n    image: registry.lab/beacon/api:1.4.2\n    depends_on: [db]\nvolumes:\n  pgdata:',
    q: 'Predict the behaviour on the first `docker compose up -d` when PostgreSQL takes three seconds to initialise, and after `docker compose down && docker compose up -d`.',
    choices: ['First up: api starts as soon as db\'s container starts, gets `Connection refused`, and crashes or restarts. After down/up: the data in `pgdata` is still there', 'First up: api waits for PostgreSQL to accept connections. After down/up: the data is gone', 'First up: Compose refuses to start api until db is healthy. After down/up: the data is still there', 'First up: both start fine. After down/up: a new empty volume is created'],
    a: 0, rationale: 'Plain `depends_on` orders container start only; readiness needs a healthcheck on `db` and `condition: service_healthy`. A named volume survives `down` (only `down -v` deletes it).',
    misconception: '`depends_on` is read as "wait until ready", and `down` is feared as data loss.' });
  Q({ id: 'q-m07-b06', moduleId: 'M07', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m07-04'], remediation: 'les-m07-04',
    q: 'A Beacon container shows `(unhealthy)` in `docker ps`. What does Docker Engine itself do about it?',
    choices: ['Nothing beyond recording the status; Compose `condition: service_healthy` and orchestrators act on it, and the check\'s output is in `docker inspect` under `State.Health`', 'Restarts the container after the configured retries', 'Stops publishing its ports until it is healthy again', 'Sends SIGTERM and waits for a clean shutdown'],
    a: 0, rationale: 'The HEALTHCHECK result is displayed and exposed; the engine does not restart or isolate on it. Restart policies react to exit, not to health.',
    misconception: 'Health status is assumed to drive restarts the way Kubernetes liveness does.' });
  Q({ id: 'q-m07-b07', moduleId: 'M07', pool: 'bank', type: 'explain', difficulty: 2, objectiveIds: ['obj-m07-01', 'obj-m07-04'], remediation: 'les-m07-04',
    q: 'Explain why the Beacon image sets `USER beacon` with a fixed UID, what the process can no longer do, and how you prove at runtime that it worked.',
    rubric: ['Root in a container is root on the shared kernel unless user namespaces remap it', 'A fixed UID (e.g. 10001) makes volume and bind-mount ownership consistent', 'Lists at least two consequences: no ports below 1024, no writes outside owned paths, no runtime package installs', 'Proof: `docker exec ... id -u` prints the UID and a write to /app fails with permission denied'],
    answer: 'The container shares the host kernel, so a process running as root inside is root on that kernel unless user namespaces remap it; an unprivileged user limits what a compromised Beacon can do. Creating the user with a fixed UID such as 10001 means files copied with `--chown` and volumes can be owned consistently across hosts. The process then cannot bind ports below 1024 (so it listens on 8080 and the publish maps lower ports if needed), cannot write anywhere it does not own (so writable paths are declared volumes or /tmp), and cannot install packages at runtime. Proof is `docker exec beacon-api id -u` printing 10001 and `docker exec beacon-api touch /app/x` failing with permission denied, recorded as a before/after pair.',
    rationale: 'The objective requires an unprivileged user and evidence that it is in effect, not just a Dockerfile line.',
    misconception: 'Isolation is assumed to make root inside a container harmless.' });
  Q({ id: 'q-m07-b08', moduleId: 'M07', pool: 'bank', type: 'order', difficulty: 2, objectiveIds: ['obj-m07-02'], remediation: 'les-m07-03',
    q: 'Order the checks to trace a host request to a Beacon socket inside a container, from the outside in.',
    steps: ['Confirm the publish mapping with `docker port beacon-api`', 'Confirm the container is on the expected network with `docker inspect -f "{{.NetworkSettings.Networks}}"`', 'List listening sockets inside with `docker exec beacon-api ss -ltnp` (or nsenter from the host)', 'Make a request from inside the container to 127.0.0.1:8080 to prove the process serves', 'Make the request from the host through the published port and compare the error'],
    rationale: 'Outside in: mapping, network membership, listener address, in-container request, then the host request whose error now discriminates loopback binding from a missing publish.',
    misconception: 'Starting with `--network host` or restarting removes the evidence that tells loopback from publish problems apart.' });
  Q({ id: 'q-m07-b09', moduleId: 'M07', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m07-05'], remediation: 'les-m07-05',
    q: 'Why does the course deploy by image digest rather than by tag when it matters?',
    choices: ['A tag is a mutable pointer that a re-push can move; a digest identifies exactly one manifest forever, so what ran in staging is what runs in production', 'Digests pull faster because they skip the registry', 'Tags cannot be used with multi-platform images', 'Kubernetes does not support tags in `image:`'],
    a: 0, rationale: 'Digests are content addresses; tags are names. Promotion by digest is how you know the tested artefact is the deployed one.',
    misconception: 'Tags that look like versions are assumed to be immutable.' });
  Q({ id: 'q-m07-b10', moduleId: 'M07', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m07-02', 'obj-m07-03'], remediation: 'les-m07-03',
    context: '$ docker logs beacon-api | tail -1\npsycopg.OperationalError: could not translate host name "beacon-db" to address: Name or service not known\n$ docker inspect -f "{{json .NetworkSettings.Networks}}" beacon-api | jq keys\n["bridge"]\n$ docker inspect -f "{{json .NetworkSettings.Networks}}" beacon-db | jq keys\n["beacon-net"]',
    q: 'What is the cause of the lookup failure?',
    choices: ['The api container is on the default bridge, which has no name resolution, while the database is on the user-defined `beacon-net`; start the api with `--network beacon-net`', 'PostgreSQL is not running; start it', 'The database port is not published to the host', 'The embedded DNS server is down; restart Docker'],
    a: 0, rationale: 'Container names resolve only on user-defined networks via the embedded DNS at 127.0.0.11, and only among members of the same network. The api joined the default bridge.',
    misconception: 'Name resolution between containers is assumed to be global.' });

  Q({ id: 'q-m07-g01', moduleId: 'M07', pool: 'gate', type: 'predict', difficulty: 2, objectiveIds: ['obj-m07-01', 'obj-m07-04'], remediation: 'les-m07-01',
    context: '# /app/start.sh (ENTRYPOINT ["/app/start.sh"])\n#!/bin/sh\npython -m beacon.api --port 8080 &\n\n$ docker run -d --name beacon-api registry.lab/beacon/api:1.4.2',
    q: 'Predict `docker ps -a` for this container a few seconds later.',
    choices: ['`Exited (0)`: the script backgrounds Beacon and reaches end of file, so PID 1 exits and the container is torn down with it', '`Up`: Beacon keeps the container alive because it is still running', '`Exited (1)`: Beacon fails because it is not PID 1', '`Restarting`: Docker restarts containers whose entrypoint returns'],
    a: 0, rationale: 'The container lives as long as PID 1. The shell script is PID 1, Beacon is a background child, the script exits 0, and the kernel ends the namespace. `exec python ...` fixes it.',
    misconception: 'Background processes are assumed to keep a container alive; only PID 1 does.' });
  Q({ id: 'q-m07-g02', moduleId: 'M07', pool: 'gate', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m07-01'], remediation: 'les-m07-02',
    context: '$ docker build -t registry.lab/beacon/api:1.4.2 .\n[+] Building 241.3s\n => [internal] load build context          38.2s\n => => transferring context: 412.55MB\n => [3/6] COPY . /app                        2.1s\n => [4/6] RUN pip install -r requirements.txt   190.4s\n$ docker history registry.lab/beacon/api:1.4.2 | head -3\nIMAGE  CREATED  CREATED BY                  SIZE\n<..>   1 min    COPY . /app                 405MB\n<..>   1 min    RUN pip install ...         210MB\n$ ls -a\n.  ..  .git  .venv  Dockerfile  beacon  data  requirements.txt',
    q: 'Which two changes address the evidence?',
    choices: ['Add a `.dockerignore` excluding `.git`, `.venv` and `data`, and copy `requirements.txt` before the install so the pip layer is cached on code changes', 'Use `--no-cache` on every build and a bigger builder', 'Switch to `ADD` instead of `COPY` for faster transfers', 'Move `requirements.txt` after `COPY . /app` so it is copied once'],
    a: 0, rationale: 'A 412MB context and a 405MB COPY layer mean the virtualenv, git history and data are being sent and baked in; the install reruns on every build because the whole tree is copied before it.',
    misconception: 'Slow builds are blamed on the machine rather than on what the context contains and the layer order.' });
  Q({ id: 'q-m07-g03', moduleId: 'M07', pool: 'gate', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m07-03'], remediation: 'les-m07-03',
    q: 'Which statement about named volumes and bind mounts is correct?',
    choices: ['A named volume is engine-managed and survives `docker rm` of every container using it; a bind mount shows a host path inside and inherits host ownership and permissions', 'Both are deleted when the last container using them is removed', 'A bind mount is the recommended home for a PostgreSQL data directory', 'Named volumes are deleted by plain `docker compose down`'],
    a: 0, rationale: 'Named volumes live under Docker\'s control and outlive containers; `down` keeps them and only `down -v` removes them. Bind mounts are for host files you edit, not for a database directory.',
    misconception: 'Volume lifetime is conflated with container lifetime.' });
  Q({ id: 'q-m07-g04', moduleId: 'M07', pool: 'gate', type: 'explain', difficulty: 2, objectiveIds: ['obj-m07-04'], remediation: 'les-m07-04',
    q: 'A Beacon container takes exactly ten seconds to stop and PostgreSQL logs `unexpected EOF on client connection` each time. Explain the two stacked causes and the change that makes the stop clean, and say what `--init` would and would not have fixed.',
    rubric: ['Shell-form CMD makes sh PID 1, which does not forward SIGTERM', 'As PID 1, Python ignores SIGTERM unless a handler is installed', 'Fix: exec-form ENTRYPOINT plus a SIGTERM handler that drains and closes connections, verified by sub-second stop and exit 0', '`--init` forwards signals and reaps but does not drain in-flight work or close the database connection'],
    answer: 'Two things stack. The image used the shell form, so `/bin/sh -c` was PID 1; Docker sent SIGTERM to the shell, which ignored it, and after ten seconds SIGKILL ended everything (exit 137) with the database connection cut mid-stream. Even in exec form Python would have ignored SIGTERM, because the kernel does not apply default signal actions to PID 1. The fix is both: `ENTRYPOINT ["python", "-m", "beacon.api"]` so Python is PID 1, and a `signal.signal(SIGTERM, handler)` that stops accepting, finishes in-flight requests, closes the database connection and exits 0. Evidence is `time docker stop` under a second, exit code 0, and no EOF errors in PostgreSQL. `--init` would make a tiny init PID 1 that forwards SIGTERM, which fixes the forwarding but not the draining: without a handler, Beacon still dies abruptly.',
    rationale: 'Graceful shutdown is a property of the process, not of the runtime flag.',
    misconception: '`--init` is believed to make any container shut down gracefully.' });
  Q({ id: 'q-m07-g05', moduleId: 'M07', pool: 'gate', type: 'order', difficulty: 2, objectiveIds: ['obj-m07-05'], remediation: 'les-m07-05',
    q: 'Order the steps to resolve `exec format error` on an amd64 node for an image built on an ARM laptop.',
    steps: ['Read the Pod log and note the exact `exec format error` line', 'Check the node architecture with `kubectl get node -o jsonpath=\'{..nodeInfo.architecture}\'`', 'Inspect the image manifest with `docker buildx imagetools inspect` and confirm it is arm64-only', 'Rebuild with `docker buildx build --platform linux/amd64,linux/arm64 --push`', 'Deploy the new index digest and confirm `uname -m` inside a Pod matches the node', 'Verify the user path through the Service'],
    rationale: 'Observation, then the two discriminating checks (node arch, manifest platform), then the rebuild, then deploy by digest and verify.',
    misconception: 'Jumping to scheduling or probe hypotheses wastes time; the manifest answers the question.' });

  /* ═══ M08 · Kubernetes fundamentals ═════════════════════════════ */
  Q({ id: 'q-m08-b01', moduleId: 'M08', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m08-03'], remediation: 'les-m08-03',
    context: '$ kubectl -n beacon get pods -l app=beacon-api\nNAME                          READY   STATUS    RESTARTS   AGE\nbeacon-api-7c9d8b5f4-k2x9p    1/1     Running   0          10m\nbeacon-api-7c9d8b5f4-r7qzt    1/1     Running   0          10m\n$ kubectl -n beacon get endpointslices -l kubernetes.io/service-name=beacon-api\nNAME               ADDRESSTYPE   PORTS    ENDPOINTS   AGE\nbeacon-api-x7k2q   IPv4          <unset>  <unset>     10m\n$ kubectl -n beacon get svc beacon-api -o jsonpath="{.spec.selector}"\n{"app":"beacon"}',
    q: 'Pods are Ready but the Service has no endpoints. What is the cause and the fix?',
    choices: ['The Service selector `app=beacon` matches no Pod (labels are `app=beacon-api`); change the Service selector and the slice fills', 'The Pods are not Ready; fix the readiness probe', 'kube-proxy is down; restart it', 'The Service needs `type: NodePort` to get endpoints'],
    a: 0, rationale: 'An empty slice with Ready Pods means the selector did not match. The Pod query with the Service\'s own selector confirms it. The Deployment selector is immutable, so fix the Service.',
    misconception: 'Running Pods are assumed to be reachable; selection is a separate step shown by the EndpointSlice.' });
  Q({ id: 'q-m08-b02', moduleId: 'M08', pool: 'bank', type: 'predict', difficulty: 3, objectiveIds: ['obj-m08-05', 'obj-m08-03'], remediation: 'les-m08-05',
    context: 'readinessProbe:\n  httpGet: { path: /readyz, port: http }\n  periodSeconds: 5\n  failureThreshold: 3\nlivenessProbe:\n  httpGet: { path: /healthz, port: http }\n  periodSeconds: 10\n  failureThreshold: 3\n\n# /readyz checks the database; /healthz checks only the process\n# beacon-db goes down for 90 seconds',
    q: 'Predict the Pod\'s READY column, RESTARTS and Service endpoints during the outage.',
    choices: ['READY `0/1` after about 15 s, RESTARTS unchanged, endpoints marked not ready so the Service sends no traffic; everything reverses when the database returns', 'READY `0/1` and RESTARTS climbing every 30 s as liveness fails', 'READY `1/1` throughout; probes do not check dependencies', 'The Pod is deleted and rescheduled after three failures'],
    a: 0, rationale: 'Readiness depends on the database and fails after 3 × 5 s; that removes the Pod from endpoints without a restart. Liveness checks only the process, so it keeps passing and nothing restarts.',
    misconception: 'Readiness failure is assumed to restart the container; only liveness does.' });
  Q({ id: 'q-m08-b03', moduleId: 'M08', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m08-04'], remediation: 'les-m08-04',
    context: '$ kubectl -n beacon get pods\nNAME                          READY   STATUS                       RESTARTS   AGE\nbeacon-api-5f6b7d9c8-m4wq2    0/1     CreateContainerConfigError   0          45s\n$ kubectl -n beacon describe pod beacon-api-5f6b7d9c8-m4wq2 | tail -1\n  Warning  Failed  12s (x4 over 45s)  kubelet  Error: couldn\'t find key BEACON_QUEUE_URL in ConfigMap beacon/beacon-config\n$ kubectl -n beacon get configmap beacon-config -o jsonpath="{.data}"\n{"BEACON_DB_HOST":"beacon-db","BEACON_LISTEN":"0.0.0.0:8080","BEACON_QUEUE":"redis://beacon-queue:6379/0"}',
    q: 'What is the cause and what happens after the fix?',
    choices: ['The ConfigMap key is `BEACON_QUEUE` but the Deployment references `BEACON_QUEUE_URL`; fix the key (or the reference) and the kubelet retries and starts the container without deleting the Pod', 'The image is missing; push it to the registry', 'The ConfigMap is in the wrong namespace; recreate it in `default`', 'The container crashed on a KeyError; add a liveness probe'],
    a: 0, rationale: 'The event names the object and the missing key, and the ConfigMap shows the different spelling. The container never started (no crash, no restarts); once the key exists the kubelet\'s retry succeeds.',
    misconception: 'A config error at container creation is confused with an application crash after start.' });
  Q({ id: 'q-m08-b04', moduleId: 'M08', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m08-02'], remediation: 'les-m08-02',
    q: 'A two-replica Deployment with `maxSurge: 1, maxUnavailable: 0` is rolled to an image that crash-loops. What do users experience, and why?',
    choices: ['No loss of service: the new Pod never becomes Ready, so no old Pod is removed and both old Pods keep serving while the rollout stalls', 'A full outage: both old Pods are replaced before readiness is evaluated', 'Half capacity: one old Pod is removed as soon as the new one is scheduled', 'Automatic rollback to the previous revision after the progress deadline'],
    a: 0, rationale: 'Readiness gates the rollout; with `maxUnavailable: 0` an old Pod is removed only when a new one is Ready. The Deployment does not roll back on its own; `rollout undo` is the operator\'s action.',
    misconception: 'Rollouts are assumed to replace Pods blindly, or to auto-revert on failure.' });
  Q({ id: 'q-m08-b05', moduleId: 'M08', pool: 'bank', type: 'predict', difficulty: 2, objectiveIds: ['obj-m08-01', 'obj-m08-02'], remediation: 'les-m08-01',
    context: '$ kubectl -n beacon get deploy,rs,pods\nNAME                         READY   UP-TO-DATE   AVAILABLE\ndeployment.apps/beacon-api   2/2     2            2\nNAME                                   DESIRED   CURRENT   READY\nreplicaset.apps/beacon-api-7c9d8b5f4   2         2         2\nNAME                              READY   STATUS\npod/beacon-api-7c9d8b5f4-k2x9p    1/1     Running\npod/beacon-api-7c9d8b5f4-r7qzt    1/1     Running\n$ kubectl -n beacon delete pod beacon-api-7c9d8b5f4-k2x9p',
    q: 'Predict what `kubectl get pods` shows a few seconds later and which loop made it so.',
    choices: ['Two Pods: `r7qzt` and a new name like `beacon-api-7c9d8b5f4-<random>`; the ReplicaSet controller created a replacement because status dropped below `spec.replicas`', 'One Pod until the Deployment is re-applied', 'Two Pods, `k2x9p` restarted in place with RESTARTS 1', 'Three Pods: the deleted one is kept in Terminating forever'],
    a: 0, rationale: 'Deleting a Pod leaves the ReplicaSet one short of its desired count; it creates a new Pod from the same template with a new random suffix. Pods are replaced, never repaired.',
    misconception: 'Pod deletion is expected to be permanent or to "restart" the same Pod.' });
  Q({ id: 'q-m08-b06', moduleId: 'M08', pool: 'bank', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m08-03'], remediation: 'les-m08-03',
    q: 'A Service has `port: 80` and `targetPort: 8000`; the Beacon container listens on 8080. What does an in-cluster client see, and what is the robust fix?',
    choices: ['Connections reach a Pod and are refused on 8000; set `targetPort` to the named container port `http` so the number lives only in the Pod template', 'A DNS failure for the Service name; fix CoreDNS', 'Nothing wrong: `targetPort` is ignored when `port` is set', 'A timeout; add a NetworkPolicy'],
    a: 0, rationale: 'Endpoints exist (selector and readiness are fine) but traffic is delivered to a port nothing listens on, so the Pod refuses it. Named ports prevent the Service and the Pod from drifting apart.',
    misconception: '`port` and `targetPort` are assumed to be the same thing.' });
  Q({ id: 'q-m08-b07', moduleId: 'M08', pool: 'bank', type: 'explain', difficulty: 3, objectiveIds: ['obj-m08-05'], remediation: 'les-m08-05',
    q: 'A colleague proposes deleting the readiness probe because the Pods "keep showing 0/1". Explain why that is a failed fix, what the probe is telling you, and what a legitimate probe change would look like.',
    rubric: ['The probe reports a true fact: the process cannot serve right now', 'Deleting it puts non-serving Pods back into the Service so users receive the failures directly', 'The correct move is to read the probe\'s response body/events and fix the cause (often a dependency)', 'Legitimate changes: separate liveness (process) from readiness (dependencies), adjust timeouts/periods with measurement, add a startup probe for slow starts'],
    answer: 'The readiness probe failing means Beacon answered that it cannot do its job — usually because a dependency such as the database is unreachable. Removing the probe changes what the cluster believes, not what Beacon can do: the Pods rejoin the Service and every user request now gets the 503 the probe was seeing, while the real outage is hidden behind Pods that look up. The right response is to read the probe failure (events and the probe endpoint\'s body), find the cause, fix it, and watch the Pods return to 1/1 on their own. Legitimate probe changes exist and are made with evidence: a liveness probe that checks the database must be narrowed to the process so a dependency outage does not restart every Pod; a timeout shorter than the endpoint\'s real latency under load should be relaxed with measurements; a cold start longer than the liveness budget needs a startup probe. None of those make a red thing green; they make the probe describe the process accurately.',
    rationale: 'The debrief for S16 asks exactly this: why deleting probes would have hidden the failure.',
    misconception: 'A failing check is treated as the problem rather than as the report of one.' });
  Q({ id: 'q-m08-b08', moduleId: 'M08', pool: 'bank', type: 'order', difficulty: 2, objectiveIds: ['obj-m08-01', 'obj-m08-04'], remediation: 'les-m08-01',
    q: 'Order the reading sequence this course teaches for a Pod that is not serving.',
    steps: ['`kubectl get pod` for phase, READY and RESTARTS', '`kubectl describe pod` for conditions and the recent events', '`kubectl logs` (with `--previous` if it restarted)', 'Query the owning object (Deployment/ReplicaSet) and the Service\'s EndpointSlice', 'Form hypotheses from the loop the evidence names (scheduler, kubelet pull, config, probes, process) and pick the discriminating check', 'Fix the owning object, not the Pod, and verify through the Service'],
    rationale: 'Phase and columns first, then events, then logs, then the ownership chain and endpoints; the loop that recorded the evidence tells you where the gap is.',
    misconception: 'Editing or deleting the Pod first destroys the evidence and is reverted by its owner anyway.' });
  Q({ id: 'q-m08-b09', moduleId: 'M08', pool: 'bank', type: 'diagnose', difficulty: 2, objectiveIds: ['obj-m08-04'], remediation: 'les-m08-04',
    context: '$ kubectl -n beacon describe pod beacon-worker-8d7c6b5a4-p9x1 | tail -4\n  Normal   Pulling  2m (x4 over 5m)   kubelet  Pulling image "registry.lab/beacon/worker:1.4.3"\n  Warning  Failed   2m (x4 over 5m)   kubelet  Failed to pull image "registry.lab/beacon/worker:1.4.3": rpc error: code = Unknown desc = failed to pull and unpack image: unauthorized: authentication required\n  Warning  Failed   2m (x4 over 5m)   kubelet  Error: ErrImagePull\n  Normal   BackOff  30s (x12 over 5m) kubelet  Back-off pulling image "registry.lab/beacon/worker:1.4.3"',
    q: 'What is the cause and the correct fix?',
    choices: ['The node cannot authenticate to the private registry; create a `kubernetes.io/dockerconfigjson` Secret and reference it in `imagePullSecrets` (Pod or service account)', 'The tag does not exist; push 1.4.3', 'The node has no network path to registry.lab; add a NAT route', 'The scheduler placed the Pod on the wrong node; add a nodeSelector'],
    a: 0, rationale: 'The message says `unauthorized: authentication required`: the registry was reached and refused the pull. A missing tag says `manifest unknown`; a network problem times out or says `no such host`. The Pod is already scheduled; the events come from the kubelet.',
    misconception: 'All pull failures are treated alike; the message text distinguishes credentials, missing tags and network path.' });
  Q({ id: 'q-m08-b10', moduleId: 'M08', pool: 'bank', type: 'mcq', difficulty: 1, objectiveIds: ['obj-m08-01'], remediation: 'les-m08-01',
    q: 'Which component assigns a Pod to a node, and which one then starts its containers?',
    choices: ['The scheduler writes `nodeName`; the kubelet on that node starts the containers and reports status', 'The kubelet picks a node; the API server starts containers', 'The controller manager both assigns and starts', 'kube-proxy assigns; the scheduler starts'],
    a: 0, rationale: 'Scheduling is choosing a node for an unassigned Pod; running it is the kubelet\'s job. Each is a separate loop with separate events.',
    misconception: 'The control plane is imagined as one program that "runs" Pods.' });

  Q({ id: 'q-m08-g01', moduleId: 'M08', pool: 'gate', type: 'diagnose', difficulty: 3, objectiveIds: ['obj-m08-05'], remediation: 'les-m08-05',
    context: '$ kubectl -n beacon get pods\nNAME                          READY   STATUS    RESTARTS      AGE\nbeacon-api-5f6b7d9c8-m4wq2    0/1     Running   6 (40s ago)   9m\n$ kubectl -n beacon describe pod beacon-api-5f6b7d9c8-m4wq2 | grep -E "Liveness|Killing|Started"\n  Warning  Unhealthy  Liveness probe failed: Get "http://10.244.0.14:8080/readyz": context deadline exceeded (Client.Timeout exceeded while awaiting headers)\n  Normal   Killing    Container api failed liveness probe, will be restarted\n  Normal   Started    Started container api\n$ kubectl -n beacon logs beacon-api-5f6b7d9c8-m4wq2 --previous | tail -1\nconnecting to beacon-db:5432 ... retry 3/10',
    q: 'What is happening, and what is the correct change?',
    choices: ['The liveness probe targets `/readyz`, which waits on the database, so a dependency outage restarts a healthy process in a loop; point liveness at the process-only `/healthz`, keep `/readyz` on readiness, and fix the database', 'Beacon is crashing on startup; raise the memory limit', 'The node is overloaded; add CPU requests', 'The probe timeout is too short for a healthy process; delete the liveness probe'],
    a: 0, rationale: 'Restarts with `Liveness probe failed` and no traceback in the previous log means the probe, not the process, is ending the container; the probe path checks the database. Liveness must not depend on dependencies.',
    misconception: 'Mounting restarts are assumed to be crashes; and deleting the probe is treated as a fix rather than as hiding the fault.' });
  Q({ id: 'q-m08-g02', moduleId: 'M08', pool: 'gate', type: 'predict', difficulty: 2, objectiveIds: ['obj-m08-04', 'obj-m08-02'], remediation: 'les-m08-04',
    context: '# Deployment template\nenvFrom:\n  - configMapRef: { name: beacon-config }\n\n$ kubectl -n beacon patch configmap beacon-config -p \'{"data":{"BEACON_LISTEN":"0.0.0.0:9090"}}\'\n$ kubectl -n beacon exec deploy/beacon-api -- sh -c \'echo $BEACON_LISTEN\'',
    q: 'Predict the output of the `exec`, and what makes the new value take effect.',
    choices: ['`0.0.0.0:8080` — environment is read at container start; `kubectl rollout restart deployment/beacon-api` creates Pods that see the new value', '`0.0.0.0:9090` — ConfigMap changes propagate to environment variables within a minute', 'An error — patching a ConfigMap in use is rejected', 'Empty — the patch removed the other keys'],
    a: 0, rationale: 'Environment variables are fixed at container start. Mounted ConfigMap volumes refresh (except subPath), but `envFrom` does not; a rollout restart is the safe, readiness-gated way to pick it up.',
    misconception: 'ConfigMap edits are expected to be live for all consumption styles.' });
  Q({ id: 'q-m08-g03', moduleId: 'M08', pool: 'gate', type: 'mcq', difficulty: 2, objectiveIds: ['obj-m08-02'], remediation: 'les-m08-02',
    q: 'After `kubectl rollout undo deployment/beacon-api`, which of these is true?',
    choices: ['The previous ReplicaSet is scaled back up under the same surge rules and the undo appears as a new revision; ConfigMaps, Secrets and database migrations are untouched', 'All objects changed by the release, including ConfigMaps, revert', 'The old Pods are resurrected with their previous names and IPs', 'Undo is instantaneous and bypasses readiness probes'],
    a: 0, rationale: 'Undo restores the Pod template by scaling an old ReplicaSet up — a rollout like any other, gated on readiness. Nothing outside the Deployment is reverted.',
    misconception: '`rollout undo` is imagined as a snapshot restore of the whole release.' });
  Q({ id: 'q-m08-g04', moduleId: 'M08', pool: 'gate', type: 'explain', difficulty: 2, objectiveIds: ['obj-m08-03', 'obj-m08-01'], remediation: 'les-m08-03',
    q: 'Describe how you prove the user path for Beacon inside the cluster, from Service name to HTTP response, and name the distinct error signature for each of: Service missing, no endpoints, targetPort mismatch.',
    rubric: ['Uses a throwaway Pod in the namespace to resolve the Service name and make a real HTTP request through it, not to a Pod IP', 'Checks the EndpointSlice for ready endpoints and the resolved target port', 'Service missing / DNS: NXDOMAIN or "server can\'t find"; no endpoints: immediate "Failed to connect" on the Service address; targetPort mismatch: "Connection refused" from a Pod', 'States that a 200/202 through the Service name is the proof, not `kubectl get svc`'],
    answer: 'From a throwaway Pod in the `beacon` namespace, resolve `beacon-api` (expect the ClusterIP) and `curl` `http://beacon-api/healthz`, then a real `POST /v1/status`; a 200 and a 202 through the name is the proof. Alongside, `kubectl get endpointslices -l kubernetes.io/service-name=beacon-api` should list ready Pod addresses and show the resolved target port 8080. If the name does not resolve (NXDOMAIN), the Service is missing in that namespace or CoreDNS is unhealthy. If it resolves but the connection fails immediately, the slice is empty: the selector matched no Ready Pod. If the connection is refused after reaching a Pod, the target port is wrong or Beacon is listening elsewhere. Hitting a Pod IP directly would prove only that the Pod serves, not the path users take.',
    rationale: 'Each failure mode has a distinct signature; the proof is a real response through the Service name.',
    misconception: 'A Service showing a ClusterIP in `kubectl get svc` is mistaken for a working path.' });
  Q({ id: 'q-m08-g05', moduleId: 'M08', pool: 'gate', type: 'order', difficulty: 2, objectiveIds: ['obj-m08-02', 'obj-m08-05'], remediation: 'les-m08-02',
    q: 'Order the steps of a safe image rollout for Beacon on Kubernetes.',
    steps: ['Change the image in the Deployment manifest to the new digest and set the `kubernetes.io/change-cause` annotation', 'Apply and follow `kubectl rollout status` with a timeout', 'Watch new Pods pass readiness before old ones are removed', 'If the rollout stalls, read the new Pod\'s events and logs, then `kubectl rollout undo`', 'Verify the user path through the Service after the rollout completes or after the undo', 'Record the revision history and the verification as evidence'],
    rationale: 'Manifest change with a cause, observed rollout gated on readiness, undo on evidence, user-path verification, and a record.',
    misconception: 'Rollouts done with `set image` from a shell and no status watch leave no record and no gate.' });

  /* review prompts for M05–M08 (changed symptoms and short recall, never the same items) */
  LX.sreReviews.push(
    { id: 'rev-m05-01', objectiveIds: ['obj-m05-01'], kind: 'changed-symptom', prompt: 'The ALB now returns 504 for POSTs while GETs are fine and targets are healthy. Which hop, and what is the one difference from a 503 or 502?', answer: 'The target accepted the connection but did not answer within the ALB idle timeout — a slow handler or a blocked database call on the POST path. 503 is "no healthy target"; 502 is a malformed or closed response.' },
    { id: 'rev-m05-02', objectiveIds: ['obj-m05-02'], kind: 'recall', prompt: 'Without looking: list the IAM evaluation order from the first thing checked to the last, and say which single result ends evaluation immediately.', answer: 'Explicit deny (ends evaluation immediately), SCP, resource-based policy, permission boundary, session policy, identity-based policy; otherwise implicit deny.' },
    { id: 'rev-m05-03', objectiveIds: ['obj-m05-03', 'obj-m05-05'], kind: 'changed-symptom', prompt: 'After az1 fails, az2 tasks serve existing traffic but cannot pull images or call the geo API. Which inventory row was wrong and what is the fix?', answer: 'The NAT gateway row: a single NAT in az1 serving both private subnets. One NAT per AZ with per-AZ route tables (and ECR endpoints so pulls need no NAT).' },
    { id: 'rev-m06-01', objectiveIds: ['obj-m06-02'], kind: 'changed-symptom', prompt: 'A plan shows `+/-` instead of `-/+` on `docker_container.api`. What changed in the configuration, and what must be true for apply to succeed?', answer: '`lifecycle { create_before_destroy = true }` was added; the new and old containers must be able to coexist (unique name, no shared host port).' },
    { id: 'rev-m06-02', objectiveIds: ['obj-m06-04'], kind: 'recall', prompt: 'Without looking: which S3 backend argument enables state locking at the pinned Terraform version, and what is the status of the DynamoDB table approach?', answer: '`use_lockfile = true`; the `dynamodb_table` argument is deprecated and should not be added to new configurations.' },
    { id: 'rev-m06-03', objectiveIds: ['obj-m06-03', 'obj-m06-05'], kind: 'changed-symptom', prompt: 'After a refactor the plan reads `docker_volume.pgdata has moved to module.beacon.docker_volume.pgdata` and nothing else. Is any data at risk, and what do you do with the `moved` block afterwards?', answer: 'No: a move only changes the address in state. Keep the block until every state using the configuration has applied it, then remove it.' },
    { id: 'rev-m07-01', objectiveIds: ['obj-m07-02'], kind: 'changed-symptom', prompt: 'The host curl now returns `curl: (7) Failed to connect to 127.0.0.1 port 8080: Connection refused` instead of a reset. Which check changed its answer, and what is the likely cause?', answer: '`docker port` — the port is no longer published (or the container is not running). A reset pointed at a loopback bind inside; a refusal on the host means nothing is listening on the host port.' },
    { id: 'rev-m07-02', objectiveIds: ['obj-m07-04'], kind: 'recall', prompt: 'Without looking: what does `docker stop` send, how long does it wait, what does it send next, and what exit code does that produce?', answer: 'SIGTERM to PID 1 (or STOPSIGNAL), waits 10 seconds by default, then SIGKILL; exit code 137.' },
    { id: 'rev-m07-03', objectiveIds: ['obj-m07-05', 'obj-m07-03'], kind: 'changed-symptom', prompt: 'The same `exec format error` appears, but `imagetools inspect` now shows a manifest list with both linux/amd64 and linux/arm64. What is the next hypothesis?', answer: 'The node pulled by a stale digest or tag before the multi-platform push, or the Deployment pins the old single-platform digest; compare the running image digest with the new index digest.' },
    { id: 'rev-m08-01', objectiveIds: ['obj-m08-05'], kind: 'changed-symptom', prompt: 'Pods show `0/1 Running` with RESTARTS climbing and events `Startup probe failed`. Which probe budget is wrong and which other probes are running meanwhile?', answer: 'The startup probe\'s `failureThreshold × periodSeconds` is shorter than the cold start; readiness and liveness are not evaluated until it succeeds, so the restarts come from the startup probe itself.' },
    { id: 'rev-m08-02', objectiveIds: ['obj-m08-03'], kind: 'recall', prompt: 'Without looking: which label selects the EndpointSlices of a Service, and what two conditions must a Pod meet to appear as a ready endpoint?', answer: '`kubernetes.io/service-name=<service>`; the Pod must match the Service selector and have its Ready condition true.' },
    { id: 'rev-m08-03', objectiveIds: ['obj-m08-04', 'obj-m08-01'], kind: 'changed-symptom', prompt: 'The Pod status is now `ImagePullBackOff` and the event says `manifest unknown` rather than `unauthorized`. What changed in the diagnosis?', answer: 'Credentials are fine; the tag or digest does not exist in the registry — a typo or an image never pushed. Push the artefact or correct the reference; no pull secret change is needed.' }
  );
})();
